import React from "react";

const ResultsSection = ({ results }) => (
  <div style={{ background: "white", padding: "25px", marginTop: "40px", borderRadius: "10px" }}>
    <h2>Prediction Results</h2>
    <p><strong>Accuracy:</strong> {results?.accuracy}</p>
    <p><strong>Threats:</strong> {results?.threats}</p>
    <p><strong>Good Points:</strong> {results?.good_points}</p>
    <p><strong>Alarming Points:</strong> {results?.alarming_points}</p>
  </div>
);

export default ResultsSection;
